
-- =========================================
-- FINANCE: Financial Management System
-- =========================================

-- 1. Revenue generated by orders
CREATE TABLE order_revenue (
    revenue_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    order_id VARCHAR(30) NOT NULL,
    revenue_amount NUMERIC(12, 2) NOT NULL
        CHECK (revenue_amount >= 0),
    recognized_at TIMESTAMP NOT NULL,
    FOREIGN KEY (order_id) REFERENCES orders(order_id),
    UNIQUE (order_id)
);

-- 2. Warehouse operating expenses
CREATE TABLE warehouse_expenses (
    expense_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    warehouse_id VARCHAR(30) NOT NULL,
    expense_category VARCHAR(100) NOT NULL,
    expense_amount NUMERIC(12, 2) NOT NULL
        CHECK (expense_amount >= 0),
    expense_timestamp TIMESTAMP NOT NULL,
    description TEXT,
    FOREIGN KEY (warehouse_id) REFERENCES warehouses(warehouse_id)
);

-- 3. Shipping costs
CREATE TABLE shipping_costs (
    shipping_cost_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    shipment_id VARCHAR(30) NOT NULL,
    shipping_amount NUMERIC(12, 2) NOT NULL
        CHECK (shipping_amount >= 0),
    recorded_at TIMESTAMP NOT NULL,
    FOREIGN KEY (shipment_id) REFERENCES shipments(shipment_id)
);
